INSERT INTO `events` VALUES ('01a07b0e-f515-701c-bd84-cfde1671d548',1,'Blood Donation Drive 2026','Blood Drive 2026','blood-donation-drive-2026','BD26','Annual corporate Blood Donation Drive in partnership with the National Blood Centre. Every donation can save up to three lives.','Annual corporate blood donation drive.',1,'physical','public','registration_open','/storage/event-covers/50af3674-7346-45e8-a22f-3559bbee2b7f.png',NULL,'[]','MARCOM & HR',2,'Sarah Jenkins','+60 3-9280 1234','hr.cambodia@rhbgroup.com','2026-11-17 02:00:00','2026-11-17 10:00:00','Asia/Phnom_Penh','2026-09-07 09:49:32','2026-10-05 09:49:32',150,1,40,'automatic',1,'2026-10-04 09:49:32','email','Level 9, RHB Bank (Cambodia) Head Office','Phnom Penh Tower, No. 445 Preah Monivong Boulevard, Sangkat Boeng Prolit, Khan 7 Makara','Phnom Penh',NULL,'Cambodia',NULL,NULL,NULL,NULL,NULL,'#ef3e42','#f16265','Donors must be 18–60 years old, weigh at least 45kg, and be in good health with adequate rest.',1,'2026-09-07 08:49:32',NULL,'2026-09-07 08:49:32','2026-09-08 05:39:17'),('01a07b0e-f521-715e-ad1f-09bf5531cc44',1,'The 31st Angkor Wat International Half Marathon','Angkor Wat Int\'l Half Marathon','angkor-wat-half-marathon-2026','AWHM26','The Angkor Wat International Half Marathon is held on the first Sunday of December in Siem Reap, Cambodia, starting and finishing on the causeway in front of Angkor Wat inside the Angkor Archaeological Park (a UNESCO World Heritage Site). First run in 1996 and organised in aid of landmine survivors and persons with disabilities, the 2026 edition is the 31st. Distances: 3KM fun run, 5KM, 10KM and the 21.1KM half marathon, with wheelchair races.','First Sunday of December in Siem Reap – 3KM / 5KM / 10KM / 21KM half marathon.',2,'physical','public','registration_open','/storage/event-covers/97b96d9c-259c-4666-a5a1-bb8915063d9f.png',NULL,'[]','MARCOM & HR',3,'RHB Cambodia Marcom','+60 3-9280 5678','kh.marcom@rhbgroup.com','2026-12-05 22:00:00','2026-12-06 03:00:00','Asia/Phnom_Penh','2026-09-07 08:49:32','2026-11-29 16:59:00',79,1,150,'automatic',1,'2026-11-22 16:59:00','email','Angkor Wat','Angkor Wat causeway, Angkor Archaeological Park','Siem Reap','Siem Reap Province','Cambodia','17000',13.4124693,103.8669857,NULL,NULL,'#0067b1','#5bc2e7','Participants take part at their own risk and must accept the official event waiver and release of liability. The event is run in aid of landmine survivors and persons with disabilities in Cambodia.',1,'2026-09-07 08:49:32',NULL,'2026-09-07 08:49:32','2026-09-08 05:34:30'),('01a07f4b-f490-70ae-ab72-988eb8856043',NULL,'RHB Badminton Doubles Tournament 2026','Badminton 2026','rhb-badminton-doubles-tournament-2026','RHBB26','RHB\'s staff badminton doubles tournament returns this October.\n\nFormat: doubles only. Every player registers individually and names their partner — both halves of a pair must register for the entry to be confirmed. 20 pairs (40 players) will be accepted; once full, further sign-ups join the waiting list and are promoted automatically if a pair drops out.\n\nBring your own racket. Shuttlecocks, water and light refreshments provided. Wear proper court shoes (non-marking soles).','Staff doubles badminton tournament — register as a pair. 20 pairs (40 players), with a waiting list.',2,'physical','public','upcoming',NULL,NULL,'[]','MARCOM & HR',1,NULL,NULL,'sports@rhbgroup.com','2026-10-27 07:00:00','2026-10-27 11:00:00','Asia/Phnom_Penh','2026-10-05 02:00:00','2026-10-15 11:00:00',40,1,20,'automatic',1,NULL,'email','T Sport — T- Badminton Courts',NULL,'Phnom Penh',NULL,'Cambodia',NULL,NULL,NULL,'https://www.google.com/maps/search/?api=1&query=T%20Sport%20Badminton%20Phnom%20Penh',NULL,'#0f172a','#2563eb',NULL,1,NULL,NULL,'2026-09-08 04:34:39','2026-09-08 05:47:58');
