DROP TABLE IF EXISTS `registrations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `registrations` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `participant_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `registration_number` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `registration_sequence` int NOT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `attendance_status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'not_checked_in',
  `waitlist_priority` int NOT NULL DEFAULT '0',
  `queue_position_cache` int DEFAULT NULL,
  `source` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `secure_access_token` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `registered_at` datetime NOT NULL,
  `confirmed_at` datetime DEFAULT NULL,
  `waitlisted_at` datetime DEFAULT NULL,
  `promoted_at` datetime DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `rejected_at` datetime DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `checked_in_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `registrations_registration_number_unique` (`registration_number`),
  UNIQUE KEY `registrations_secure_access_token_unique` (`secure_access_token`),
  KEY `registrations_event_id_index` (`event_id`),
  KEY `registrations_participant_id_index` (`participant_id`),
  KEY `registrations_status_index` (`status`),
  KEY `registrations_attendance_status_index` (`attendance_status`),
  KEY `registrations_registered_at_index` (`registered_at`),
  KEY `registrations_event_status_idx` (`event_id`,`status`),
  KEY `registrations_event_attendance_idx` (`event_id`,`attendance_status`),
  KEY `registrations_confirmed_at_idx` (`confirmed_at`),
  KEY `registrations_waitlisted_at_idx` (`waitlisted_at`),
  KEY `registrations_promoted_at_idx` (`promoted_at`),
  CONSTRAINT `registrations_event_id_foreign` FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE CASCADE,
  CONSTRAINT `registrations_participant_id_foreign` FOREIGN KEY (`participant_id`) REFERENCES `participants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
